installer-gui-script.script:

function installation_check() {
    if (system.compareVersions(system.version.ProductVersion, '13.0') < 0) {
        my.result.title = 'macOS version not supported';
        my.result.message = 'This community package requires macOS 13.0 or later.';
        my.result.type = 'Fatal';
        return false;
    }
    if (system.hardware.architecture != 'ARCH_PLACEHOLDER') {
        my.result.title = 'Wrong architecture package';
        my.result.message = 'This package was built for ARCH_PLACEHOLDER. Download the package for this Mac architecture.';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
